    const std::vector<ObjectsCase>& objectsCases() {
      static const std::vector<ObjectsCase> cases = [] {
        std::vector<ObjectsCase> ret;
        for (const RawCase& r : k_cases) {
          ObjectsCase c;
          c.name = r.name; c.layout = r.layout; c.features = r.features; c.cartesian = r.cartesian;
          for (int i = 0; i < 3; i++) c.position[i] = r.position[i];
          c.width = r.width; c.height = r.height; c.depth = r.depth; c.gain = r.gain; c.diffuse = r.diffuse;
          c.channelLock = r.channelLock; c.channelLockMaxDistance = r.channelLockMaxDistance;
          c.divergence = r.divergence; c.divergenceRange = r.divergenceRange;
          c.divergenceCartesian = r.divergenceCartesian;
          c.zones.assign(k_zones + r.zonesOffset, k_zones + r.zonesOffset + r.zonesCount);
          c.screenRef = r.screenRef;
          c.screenEdgeLockHorizontal = r.screenEdgeLockH; c.screenEdgeLockVertical = r.screenEdgeLockV;
          c.usesExtent = r.usesExtent;
          c.direct.assign(k_gains + r.gainsOffset, k_gains + r.gainsOffset + r.numChannels);
          c.diffuseGains.assign(k_gains + r.gainsOffset + r.numChannels, k_gains + r.gainsOffset + 2 * r.numChannels);
          ret.push_back(std::move(c));
        }
        return ret;
      }();
      return cases;
    }

